class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def removeZeroSum(nums):
    dummy = ListNode(0, build(nums))
    last = {}
    s = 0
    cur = dummy
    while cur:
        s += cur.val
        last[s] = cur
        cur = cur.next
    s = 0
    cur = dummy
    while cur:
        s += cur.val
        cur.next = last[s].next
        cur = cur.next
    return dump(dummy.next)
